import styled from 'styled-components';
import { Link } from 'react-router-dom';

/*
 * Nocturne palette, matched to the homepage (NewHome/GlobalStyle.js).
 * Those CSS variables only exist while NewHome is mounted, so the blog
 * pages hardcode the same values here to stay on theme on their own route.
 *
 *   wine   #150710   wine-2 #1e0a16   panel #22101d
 *   cream  #f0e6d8   cream-dim #b9a892   muted #8a7867
 *   brass  #c9a86a   brass-lo #8f7645
 *   alien  #7ff0be   alien-lo #3fae82
 *   line   rgba(201,168,106,.18)   line-2 rgba(201,168,106,.32)
 */

const DISPLAY = "'Megrim', 'Didot', 'Bodoni MT', Garamond, serif";
const SERIF = "'Didot', 'Bodoni MT', 'Hoefler Text', Garamond, 'Times New Roman', serif";
const MONO = "'SFMono-Regular', ui-monospace, Menlo, Consolas, monospace";
const UI =
  "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif";

/* ---- header ---- */

export const HeaderBar = styled.header`
  position: sticky;
  top: 0;
  z-index: 20;
  background: color-mix(in srgb, #150710 82%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(201, 168, 106, 0.18);
`;

export const HeaderInner = styled.div`
  max-width: 1060px;
  margin: 0 auto;
  padding: 0 26px;
  height: 62px;
  display: flex;
  align-items: center;
  justify-content: space-between;
`;

export const Brand = styled(Link)`
  font-family: ${DISPLAY};
  font-size: 1.6rem;
  letter-spacing: 0.04em;
  color: #f0e6d8;
  text-decoration: none;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  gap: 7px;

  span {
    color: #8f7645;
  }
  b {
    font-weight: 400;
    color: #7ff0be;
  }
  &:hover b {
    color: #f0e6d8;
  }
`;

/* The saucer from the homepage hero (NewHome/index.js, svg.craft) standing in for the "RM"
   between the :: brackets. Same path data and the same two colors as the hero's craft — but
   the stroke widths are in that 150x70 viewBox's units, so they have to be several times the
   hero's 1.4 to still land on a ~1px line once the box is squeezed down to 40px wide.
   Colors are literals here because this component tree predates the Nocturne CSS variables
   and the rest of this file is written the same way. */
export const BrandUfo = styled.svg`
  width: 40px;
  height: 25px;
  flex: none;
  overflow: visible;

  .glow {
    fill: none;
    stroke: #3fae82;
    stroke-width: 5;
    filter: drop-shadow(0 0 4px rgba(127, 240, 190, 0.5));
  }
  .dome2 {
    fill: none;
    stroke: #8f7645;
    stroke-width: 4.5;
  }
  /* matches the hover the "RM" had: the green goes cream on hover */
  ${Brand}:hover & .glow {
    stroke: #f0e6d8;
  }
`;

export const NavRow = styled.nav`
  display: flex;
  align-items: center;
  gap: 24px;
  font-family: ${MONO};
  font-size: 14px;

  @media screen and (max-width: 600px) {
    gap: 16px;
    font-size: 13px;
  }
`;

export const NavA = styled.a`
  color: #b9a892;
  text-decoration: none;
  transition: color 0.18s;

  &:hover {
    color: #7ff0be;
  }

  @media screen and (max-width: 440px) {
    &.hidem {
      display: none;
    }
  }
`;

