// Flip the static robots meta to noindex while a not-found view is mounted, and
// restore the original on unmount. Keeps crawlers from indexing 200-status
// "not found" pages (the GitHub Pages SPA trick can't return a real 404).
export const useNoindex = () => {
  useEffect(() => {
    const el = document.head.querySelector('meta[name="robots"]');
    if (!el) return undefined;
    const prev = el.getAttribute('content');
    el.setAttribute('content', 'noindex');
    return () => el.setAttribute('content', prev);
  }, []);
};
